  if (G.scene === 'forest' || G.scene === 'street' || G.scene === 'plant'){ const cx = SCN.spots.car, show = G.era === 2026 || (G.era === 1993 && G.F.met_iwao) || G.era === 1960; if (show){ const d = el('div', 'carp', `<svg viewBox="-260 -190 520 200" width="520" height="200">${carSide(G.era, 0, 0, G.era === 1960 ? {} : { c: '#3a4046' })}</svg>`); d.style.left = (cx - 260) + 'px'; actors.append(d); } }
