  if (!dir) return; G.face = dir; const sp = (FAST ? 6000 : O.walk) * dt, nx = Math.max(70, Math.min(SCN.w - 70, target != null ? (dir > 0 ? Math.min(target, G.x + sp) : Math.max(target, G.x - sp)) : G.x + dir * sp)); if (nx === G.x){ dir = 0; target = null; setArrows(); } G.x = nx; stepT += sp; if (stepT > 150){ stepT = 0; AudioSys.sfx(SCN.inside && !SCN.dark ? 'step' : 'stepw'); }
