tap($('#w-left'), () => { if (busy) return; target = null; intent = null; dir = dir < 0 ? 0 : -1; setArrows(); if (!dir) walker.classList.remove('walk'); });
tap($('#w-right'), () => { if (busy) return; target = null; intent = null; dir = dir > 0 ? 0 : 1; setArrows(); if (!dir) walker.classList.remove('walk'); });
