async function go(scene, at, sfx = 'door'){ pushUndo(); AudioSys.sfx(sfx); await fade(async () => { G.scene = scene; SCN = SC[scene](G.era); G.x = (typeof at === 'number' ? at : SCN.spots[at]) + (at === 'out' ? 150 : 0); G.face = 1; buildScene(); }); await arrivals(); save(); }
